#include <spacerad/WorkbenchWidget.h>
#include <spacerad/OrbitEnvironment.h>
#include "runtime/ProjectFile.h"
#include <QApplication>
#include <QDialog>
#include <QDir>
#include <QEvent>
#include <QEventLoop>
#include <QFile>
#include <QFileDialog>
#include <QFileInfo>
#include <QLabel>
#include <QLineEdit>
#include <QPointer>
#include <QPushButton>
#include <QScrollArea>
#include <QScrollBar>
#include <QSurfaceFormat>
#include <QTableWidget>
#include <QTimer>
#include <QVTKOpenGLNativeWidget.h>
#include <iostream>
using namespace spacerad;
namespace {
Json checks=Json::array();void check(bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);std::cout<<"PASS "<<name<<std::endl;}
void write(const QString& path,const QByteArray& b){QFile f(path);if(!f.open(QIODevice::WriteOnly|QIODevice::Truncate)||f.write(b)!=b.size())throw std::runtime_error("Cannot save UI evidence");}
QPushButton* button(QWidget& w,const char* name){auto b=w.findChild<QPushButton*>(name);if(!b)throw std::runtime_error("Missing orbit button");return b;}
void field(QDialog& d,const char* name,const QString& text){auto e=d.findChild<QLineEdit*>(name);if(!e)throw std::runtime_error("Missing orbit field");e->setText(text);}
void configure(QDialog& d,const QString& py,const QString& tools,const QString& ephem,const QString& output){field(d,"spaceradOrbitPython",py);field(d,"spaceradOrbitTools",tools);field(d,"spaceradOrbitEphemeris",ephem);field(d,"spaceradOrbitOutput",output);}
void run(QDialog& d,bool cancel=false){auto s=d.findChild<OrbitEnvironmentService*>();QString error;QEventLoop loop;QTimer timer;timer.setSingleShot(true);auto done=QObject::connect(s,&OrbitEnvironmentService::stateChanged,&loop,[&](const QString& state){if(state=="completed"||state=="cancelled"||state=="failed")loop.quit();});auto failed=QObject::connect(s,&OrbitEnvironmentService::failed,&loop,[&](const QString& e){error=e;});QObject::connect(&timer,&QTimer::timeout,&loop,[&]{error="Orbit UI timed out";s->cancel();loop.quit();});timer.start(60000);button(d,"spaceradOrbitRun")->click();check(s->running()&&!button(d,"spaceradOrbitRun")->isEnabled()&&!d.findChild<QLineEdit*>("spaceradOrbitEphemeris")->isEnabled(),"Native orbit settings locked while modeling");if(cancel)QTimer::singleShot(10,&d,[&]{button(d,"spaceradOrbitCancel")->click();});if(s->running())loop.exec();QObject::disconnect(done);QObject::disconnect(failed);if(!error.isEmpty())throw std::runtime_error(error.toStdString());check(s->state()==(cancel?"cancelled":"completed"),cancel?"Native orbit cancel reaches terminal state":"Native orbit model completes and verifies");}
void close(QDialog* d){d->close();QCoreApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QCoreApplication::processEvents();}
void transport(WorkbenchWidget& host,const QString& output){QEventLoop loop;QString error;auto done=QObject::connect(&host,&WorkbenchWidget::resultReady,&loop,&QEventLoop::quit);auto fail=QObject::connect(host.service(),&AnalysisService::failed,&loop,[&](const QString& e){error=e;loop.quit();});QTimer timer;timer.setSingleShot(true);QObject::connect(&timer,&QTimer::timeout,&loop,[&]{error="Transport timed out";host.cancel();loop.quit();});timer.start(60000);host.runTo(output);loop.exec();QObject::disconnect(done);QObject::disconnect(fail);if(!error.isEmpty())throw std::runtime_error(error.toStdString());}
void openHistory(QDialog& d,const QString& path){QTimer picker,watchdog;picker.setSingleShot(true);watchdog.setSingleShot(true);bool selected=false;QObject::connect(&picker,&QTimer::timeout,&d,[&]{if(auto f=qobject_cast<QFileDialog*>(QApplication::activeModalWidget())){selected=true;f->setDirectory(path);QTimer::singleShot(80,f,[f]{QMetaObject::invokeMethod(f,"accept");});}});QObject::connect(&watchdog,&QTimer::timeout,&d,[]{if(auto w=QApplication::activeModalWidget())w->close();});picker.start(50);watchdog.start(5000);button(d,"spaceradOrbitOpen")->click();check(selected,"Historical model selected through native file dialog");}
}
int main(int argc,char** argv){QSurfaceFormat::setDefaultFormat(QVTKOpenGLNativeWidget::defaultFormat());QCoreApplication::setAttribute(Qt::AA_DontUseNativeDialogs);QApplication app(argc,argv);if(argc!=7)return 2;auto py=QFileInfo(QString::fromLocal8Bit(argv[1])).absoluteFilePath(),tools=QFileInfo(QString::fromLocal8Bit(argv[2])).absoluteFilePath(),ephem=QFileInfo(QString::fromLocal8Bit(argv[3])).absoluteFilePath(),runtime=QString::fromLocal8Bit(argv[4]),input=QString::fromLocal8Bit(argv[5]),out=QFileInfo(QString::fromLocal8Bit(argv[6])).absoluteFilePath();if(QFileInfo::exists(out)||!QDir().mkpath(out))return 2;bool passed=false;
try{WorkbenchWidget host;auto base=engine::loadProjectFile(input).project;base.events=100;host.setProject(base);host.setRuntime(loadRuntimeFile(runtime));host.resize(1150,850);host.show();app.processEvents();transport(host,out+"/before");auto before=host.project().toJson();auto oldResult=host.acceptedResult();check(!oldResult.isEmpty(),"Host has a real accepted result before orbit workflow");int changed=0,ready=0;QObject::connect(&host,&WorkbenchWidget::projectChanged,&host,[&]{++changed;});QObject::connect(&host,&WorkbenchWidget::resultReady,&host,[&](const QByteArray&){++ready;});button(host,"spaceradOrbitEnvironment")->click();app.processEvents();auto d=host.findChild<QDialog*>("spaceradOrbitDialog");check(d&&d->isVisible()&&!d->isModal(),"Shared workbench opens nonmodal orbit environment dialog");configure(*d,py,tools,ephem,out+"/model");field(*d,"spaceradOrbitGap","0");button(*d,"spaceradOrbitRun")->click();check(!d->findChild<OrbitEnvironmentService*>()->running()&&!QFileInfo::exists(out+"/model")&&!d->findChild<QLabel*>("spaceradOrbitNotice")->text().isEmpty(),"Invalid orbit settings rejected before creating output");field(*d,"spaceradOrbitGap","60");run(*d);auto report=loadOrbitModelJob(out+"/model");check(d->findChild<QTableWidget*>("spaceradOrbitSpectra")->rowCount()==2&&button(*d,"spaceradOrbitApply")->isEnabled(),"Accepted orbit summary displays two modeled source species");check(host.project().toJson()==before&&host.acceptedResult()==oldResult&&changed==0&&ready==0,"Model generation preserves host project and previous accepted result");
    d->resize(650,470);app.processEvents();auto scroll=d->findChild<QScrollArea*>("spaceradOrbitScroll");scroll->ensureWidgetVisible(d->findChild<QTableWidget*>("spaceradOrbitSpectra"));app.processEvents();check(scroll->verticalScrollBar()->maximum()>0,"Orbit dialog supports small embedding windows");d->resize(1000,900);scroll->verticalScrollBar()->setValue(0);app.processEvents();check(d->grab().save(out+"/orbit.png"),"Native orbit workflow screenshot saved");button(*d,"spaceradOrbitApply")->click();check(host.project().toJson()==Project::fromJson(report.at("project")).toJson()&&host.acceptedResult().isEmpty()&&changed==1&&ready==0,"Explicit apply replaces environment and clears stale transport result once");check(host.project().duration==680.896&&!host.project().synthetic,"Applied environment retains fractional exposure and modeled provenance");transport(host,out+"/after");check(!host.acceptedResult().isEmpty()&&ready==1,"Applied modeled spectrum completes actual Geant4 transport");close(d);
    host.setProject(base);host.showOrbitEnvironment();app.processEvents();d=host.findChild<QDialog*>("spaceradOrbitDialog");openHistory(*d,out+"/model");check(d->findChild<QTableWidget*>("spaceradOrbitSpectra")->rowCount()==2&&!d->findChild<OrbitEnvironmentService*>()->running(),"History review does not execute Python model");auto changedProject=host.project();changedProject.duration+=1;host.setProject(changedProject);auto replacement=host.project().toJson();button(*d,"spaceradOrbitApply")->click();check(host.project().toJson()==replacement&&d->findChild<QLabel*>("spaceradOrbitNotice")->text().contains("Project changed"),"Stale model apply cannot overwrite newer host project");close(d);
    host.showOrbitEnvironment();app.processEvents();d=host.findChild<QDialog*>("spaceradOrbitDialog");configure(*d,py,tools,ephem,out+"/cancel");auto cancelBefore=host.project().toJson();run(*d,true);check(!button(*d,"spaceradOrbitApply")->isEnabled()&&host.project().toJson()==cancelBefore,"Cancelled model cannot apply or change host input");close(d);
    host.showOrbitEnvironment();app.processEvents();d=host.findChild<QDialog*>("spaceradOrbitDialog");configure(*d,py,tools,ephem,out+"/close-active");button(*d,"spaceradOrbitRun")->click();QPointer<QDialog> closing=d;close(d);QFile record(out+"/close-active/model-job.json");if(!record.open(QIODevice::ReadOnly))throw std::runtime_error("Missing cancelled model record");check(closing.isNull()&&Json::parse(record.readAll().toStdString()).at("status")=="cancelled","Closing active orbit window terminates model process safely");
    passed=true;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';}write(out+"/summary.json",QByteArray::fromStdString(Json{{"passed",passed},{"checks",checks}}.dump(2)));std::cout<<checks.size()<<" native orbit UI checks; passed="<<passed<<'\n';return passed?0:1;}
